78: export const generateCookie = (name: string, value: string, opt?: CookieOptions): string => {
79:   // Cookie names prefixed with __Secure- can be used only if they are set with the secure attribute.
80:   // Cookie names prefixed with __Host- can be used only if they are set with the secure attribute, must have a path of / (meaning any path at the host)
81:   // and must not have a Domain attribute.
82:   // Read more at https://developer.mozilla.org/en-US/docs/Web/HTTP/Headers/Set-Cookie#cookie_prefixes'
83:   let cookie
84:   if (opt?.prefix === 'secure') {
85:     cookie = serialize('__Secure-' + name, value, { path: '/', ...opt, secure: true })
86:   } else if (opt?.prefix === 'host') {
87:     cookie = serialize('__Host-' + name, value, {
88:       ...opt,
89:       path: '/',
90:       secure: true,
91:       domain: undefined,
92:     })
93:   } else {
94:     cookie = serialize(name, value, { path: '/', ...opt })
95:   }
96:   return cookie
97: }
