113:       path: '/',
114:       ...opt,
115:       secure: true,
116:     })
117:   } else if (opt?.prefix === 'host') {
118:     cookie = await serializeSigned('__Host-' + name, value, secret, {
119:       ...opt,
120:       path: '/',
121:       secure: true,
122:       domain: undefined,
123:     })
124:   } else {
125:     cookie = await serializeSigned(name, value, secret, { path: '/', ...opt })
126:   }
127:   return cookie
128: }
129: 
130: export const setSignedCookie = async (
131:   c: Context,
132:   name: string,
133:   value: string,
134:   secret: string | BufferSource,
135:   opt?: CookieOptions
136: ): Promise<void> => {
137:   const cookie = await generateSignedCookie(name, value, secret, opt)
138:   c.header('set-cookie', cookie, { append: true })
139: }
